// Tabbit's binary reader.
//
// Copied in beside the generated accessor so the emitted code needs nothing
// installed. Edit it in the Tabbit repository.
//
//
// Reads the .tcb files Tabbit's binary exporter writes:
//
//   fixed8      one byte
//   fixed32     four bytes, little endian
//   fixed64     eight bytes, little endian
//   varint32    seven bits per byte, high bit set while more bytes follow,
//               at most five bytes
//   counter32   zig-zag encoded i32 written as a varint32
//   string      counter32 byte length, then that many UTF-8 bytes
//
// One of several readers of one format the exporter defines. The conformance corpus
// is what keeps them agreeing.
//
// No dependencies: everything here is core and std, so the generated crate needs no
// Cargo registry access to build.

use std::fmt;
use std::fs;
use std::io;
use std::path::Path;

/// Stamped at the head of every table file by the exporter.
/// The format is column-oriented and self-describing: the header names every column
/// and how long its block is, and a reader that meets a version it does not know stops
/// rather than guessing. 102 replaced 101 outright - a descriptor gained its encoding
/// byte - before any 101 file had shipped. 104 is the current one: four encodings joined
/// the nine, and the flags byte gained a meaning.
pub const FORMAT_VERSION: u32 = 107;

// The wire element types and kinds, as a column descriptor spells them.
pub const ELEMENT_VARINT: u8 = 0;
pub const ELEMENT_BOOL: u8 = 1;
pub const ELEMENT_I32: u8 = 2;
pub const ELEMENT_I64: u8 = 3;
pub const ELEMENT_F32: u8 = 4;
pub const ELEMENT_F64: u8 = 5;
pub const ELEMENT_STRING: u8 = 6;
pub const ELEMENT_UUID: u8 = 7;

pub const KIND_SCALAR: u8 = 0;
pub const KIND_ARRAY: u8 = 1;

// How a block's values are laid out. Raw is the layout 101 had; the others compress
// a column that repeats itself. spec/wire/tcb-v102-column-encoding.md is the contract.
pub const ENCODING_RAW: u8 = 0;
pub const ENCODING_VARINT: u8 = 1;
pub const ENCODING_DELTA: u8 = 2;
pub const ENCODING_RLE: u8 = 3;
pub const ENCODING_DELTA_RLE: u8 = 4;
pub const ENCODING_DICT: u8 = 5;
pub const ENCODING_DICT_RLE: u8 = 6;
pub const ENCODING_DICT_FRONT: u8 = 7;
pub const ENCODING_DICT_FRONT_RLE: u8 = 8;

// Composition rather than layout. An array block names an encoding for its elements and
// one for its rows' lengths, and a whole-number float block names the integer encoding its
// values travel under - so both are decoded by the cursors that already exist, one level
// down, and neither adds a decode step anywhere.
pub const ENCODING_ARRAY: u8 = 9;
pub const ENCODING_WHOLE: u8 = 10;

// A dictionary whose entries are built from a shared table of the pieces they are made of,
// which reaches what two values share in the middle and at the end where front coding can
// only reach what they share at the front.
pub const ENCODING_DICT_SEGMENT: u8 = 11;
pub const ENCODING_DICT_SEGMENT_RLE: u8 = 12;

/// An integer stream at the width its own range needs, over a base.
pub const ENCODING_BITPACK: u8 = 13;

// The file header, at fixed offsets whether or not the file is encrypted and whether or not
// it carries a MAC. spec/wire/tcb-mac-and-signature.md.
pub const MAGIC_OFFSET: usize = 0;
pub const VERSION_OFFSET: usize = 4;
pub const FLAGS_OFFSET: usize = 8;
pub const CIPHER_OFFSET: usize = 9;
pub const NONCE_OFFSET: usize = 10;
pub const MAC_OFFSET: usize = 22;
pub const KEY_CHECK_OFFSET: usize = 38;

/// Where the body begins. The header before it is always this long.
pub const HEADER_SIZE: usize = 42;

pub const NONCE_SIZE: usize = 12;
pub const MAC_SIZE: usize = 16;

/// The signature every table file starts with, and the key check under the cipher.
///
/// The same four bytes serve twice. At offset zero they are the file format signature, in
/// the clear whether or not the file is encrypted. At the key check they are under the key,
/// so a file that decrypts to something else was written with a different key - which is the
/// one thing no structural check can tell from damage.
pub const MAGIC: &[u8; 4] = b"TCB\0";

/// Bit 0 of the flags byte: from the key check on, the file is ciphertext.
pub const FLAG_ENCRYPTED: u8 = 0x01;

/// The cipher byte of a file that is not encrypted.
pub const CIPHER_NONE: u8 = 0;

/// The only cipher the format defines.
pub const CIPHER_CHACHA20: u8 = 1;

/// One column as the file describes it.
#[derive(Clone, Copy, Debug)]
pub struct Column {
    /// What identifies the column, instead of its position.
    pub tag: i32,
    pub element: u8,
    pub kind: u8,
    /// How the block's values are laid out: one of the ENCODING_* constants.
    pub encoding: u8,
    /// Total bytes of the column block - what a skip advances by.
    pub byte_length: i32,
    /// Whether the block begins with one presence bit per row, low bit first.
    ///
    /// Part of the column's shape rather than a detail of its contents: a reader that does
    /// not expect the bitmap reads it as values, so `check_column` refuses a disagreement
    /// the same way it refuses a changed kind.
    pub nullable: bool,

    /// Whether the block states, per element, which of an array's places hold a value.
    ///
    /// Independent of `nullable`: a column may say either, or both.
    /// spec/types/nullable-array-elements.md.
    pub element_nullable: bool,
}

/// A parsed header: the row count and the column descriptors that follow it.
pub struct Header {
    pub row_count: i32,
    pub columns: Vec<Column>,
}

/// What went wrong while reading a table.
#[derive(Debug)]
pub enum Error {
    /// The file ended before a value did.
    Truncated { position: usize, length: usize, wanted: usize },
    /// A varint ran past the five bytes an i32 can need.
    VarintTooLong,
    /// A length prefix was negative.
    NegativeLength,
    /// The file was written by a version this build does not read.
    UnsupportedVersion { found: u32, expected: u32 },
    /// The flags byte still says ciphertext, which is bytes that never went through [`open`].
    NotDecrypted,
    /// The flags byte named a feature beyond the one this build knows how to undo.
    UnsupportedFeatures,
    /// The file is sealed with a cipher this build does not know.
    UnknownCipher { cipher: u8 },
    /// The file is encrypted and the key given was absent or not 32 bytes.
    MissingKey,
    /// What the file decrypted to is not a table, which is what a wrong key looks like.
    WrongKey,
    /// The file does not start with the four bytes every table file starts with.
    NotATableFile,
    /// A MAC key was given and the file carries no tag, which is what a stripped one is.
    MissingMac,
    /// The file's bytes do not produce the tag it carries.
    MacMismatch,
    /// The bytes of a string were not valid UTF-8.
    InvalidUtf8,
    /// A column and the generated member disagree about shape or type.
    ///
    /// Refusal is by name and both wires, never by reading anyway: a value that might
    /// not survive the conversion is a value this format does not read.
    ColumnMismatch { field: &'static str, detail: &'static str },
    /// A run claims a length the column has no rows left for - or no length at all.
    RunLengthImplausible { field: &'static str, length: i32, rows_left: i32 },
    /// A dictionary index points outside the dictionary the block decoded.
    DictionaryIndexOutOfRange { field: &'static str, index: i32, entries: usize },
    /// A front-coded entry claims to share more bytes than the entry before it has.
    DictionaryPrefixImplausible {
        field: &'static str,
        index: i32,
        shared: i32,
        previous: usize,
    },
    /// A column block's declared length and the bytes the read consumed disagree.
    BlockLengthMismatch { tag: i32 },
    /// A column declares more bytes than the file has left to give it.
    ColumnLengthImplausible { tag: i32, byte_length: i32 },
    /// The row count is larger than a column block could hold that many rows in.
    RowCountImplausible { rows: i32, tag: i32, byte_length: i32 },
    /// A fixed array column states more elements per row than its block could hold.
    /// The blocks the columns declare and the bytes after the header do not add up.
    HeaderLengthMismatch { declared: i32, available: i32 },
    /// A lookup for a key no row carries.
    ///
    /// Raised by the generated `get_by_*_or_error` lookups, which is where a caller has
    /// said the key has to be there. `find_by_*` answers the same question with `None`.
    RecordNotFound { table: &'static str, field: &'static str, key: String },
    /// The file could not be opened or read.
    Io(io::Error),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Truncated { position, length, wanted } => write!(
                f,
                "table data ended after {} of {} bytes while {} more were expected",
                position, length, wanted
            ),
            Error::VarintTooLong => write!(f, "varint32 is longer than five bytes"),
            Error::NegativeLength => write!(f, "length is negative"),
            Error::UnsupportedVersion { found, expected } => write!(
                f,
                "table format version {} is not supported (expected {})",
                found, expected
            ),
            Error::NotDecrypted => write!(
                f,
                "the table is encrypted and was not decrypted - pass the key through open first"
            ),
            Error::UnsupportedFeatures => write!(f, "table declares unsupported features"),
            Error::UnknownCipher { cipher } => write!(
                f,
                "the file uses cipher {}, which this reader does not know",
                cipher
            ),
            Error::MissingKey => write!(
                f,
                "the file is encrypted and no key, or a key that is not 32 bytes, was given"
            ),
            Error::WrongKey => write!(
                f,
                "the file did not decrypt to a table - the key is not the one it was written with"
            ),
            Error::NotATableFile => {
                write!(f, "the file does not begin with the table file signature")
            }
            Error::MissingMac => write!(
                f,
                "the file carries no MAC and this build expects one - it was exported without \
                 a MAC key, or the field was cleared after it was written"
            ),
            Error::MacMismatch => write!(
                f,
                "the file does not match its MAC - it was altered after it was exported, or it \
                 was signed with a different key"
            ),
            Error::InvalidUtf8 => write!(f, "string bytes are not valid UTF-8"),
            Error::ColumnMismatch { field, detail } => write!(f, "{}: {}", field, detail),
            Error::RunLengthImplausible { field, length, rows_left } => write!(
                f,
                "{}: a run of {} values cannot cover the {} rows left in the column",
                field, length, rows_left
            ),
            Error::DictionaryIndexOutOfRange { field, index, entries } => write!(
                f,
                "{}: dictionary index {} is out of range - the dictionary holds {} entries",
                field, index, entries
            ),
            Error::DictionaryPrefixImplausible { field, index, shared, previous } => write!(
                f,
                "{}: dictionary entry {} shares {} bytes with an entry of {}",
                field, index, shared, previous
            ),
            Error::ColumnLengthImplausible { tag, byte_length } => write!(
                f,
                "column tag {} declares {} bytes, which the file cannot hold",
                tag, byte_length
            ),
            Error::RowCountImplausible { rows, tag, byte_length } => write!(
                f,
                "the row count {} is larger than column tag {} can hold in its {} bytes",
                rows, tag, byte_length
            ),
            Error::HeaderLengthMismatch { declared, available } => write!(
                f,
                "the columns declare {} bytes but {} follow the header",
                declared, available
            ),
            Error::BlockLengthMismatch { tag } => write!(
                f,
                "column tag {}: the block's declared length and the bytes consumed disagree",
                tag
            ),
            Error::RecordNotFound { table, field, key } => write!(
                f,
                "there is no record in table `{}` that corresponds to field `{}` value {}",
                table, field, key
            ),
            Error::Io(inner) => write!(f, "{}", inner),
        }
    }
}

impl std::error::Error for Error {}

impl From<io::Error> for Error {
    fn from(inner: io::Error) -> Self {
        Error::Io(inner)
    }
}

pub type Result<T> = std::result::Result<T, Error>;

/// Sequential reader over a table file's bytes.
///
/// Borrows rather than owns, so loading a table costs no copy of the file.
pub struct Reader<'a> {
    data: &'a [u8],
    position: usize,
}

impl<'a> Reader<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Reader { data, position: 0 }
    }

    /// Bytes consumed so far.
    /// Advances past bytes without interpreting them: an unknown column whole block.
    /// The column-oriented layout is what makes this one call the entirety of skipping.
    pub fn skip(&mut self, byte_count: i32) -> Result<()> {
        if byte_count < 0 {
            return Err(Error::NegativeLength);
        }

        // take() is the bounds check.
        self.take(byte_count as usize)?;
        Ok(())
    }

    // Promotions: a member reading a file element narrower than itself. Only the
    // mathematically lossless directions exist; check_column already refused the rest.

    /// An i32 member from i32 or varint.
    pub fn read_i32_as(&mut self, element: u8) -> Result<i32> {
        if element == ELEMENT_I32 {
            self.read_i32()
        } else {
            self.read_counter32()
        }
    }

    /// An i64 member from i64, i32 or varint.
    pub fn read_i64_as(&mut self, element: u8) -> Result<i64> {
        match element {
            ELEMENT_I64 => self.read_i64(),
            ELEMENT_I32 => Ok(self.read_i32()? as i64),
            _ => Ok(self.read_counter32()? as i64),
        }
    }

    /// An f64 member from f64, f32 or i32 - all exact in an f64.
    pub fn read_f64_as(&mut self, element: u8) -> Result<f64> {
        match element {
            ELEMENT_F64 => self.read_f64(),
            ELEMENT_F32 => Ok(self.read_f32()? as f64),
            _ => Ok(self.read_i32()? as f64),
        }
    }

    pub fn position(&self) -> usize {
        self.position
    }

    /// Bytes left to read.
    pub fn remaining(&self) -> usize {
        self.data.len() - self.position
    }

    fn take(&mut self, count: usize) -> Result<&'a [u8]> {
        if self.remaining() < count {
            return Err(Error::Truncated {
                position: self.position,
                length: self.data.len(),
                wanted: count,
            });
        }

        let slice = &self.data[self.position..self.position + count];
        self.position += count;

        Ok(slice)
    }

    pub fn read_u8(&mut self) -> Result<u8> {
        Ok(self.take(1)?[0])
    }

    pub fn read_bool(&mut self) -> Result<bool> {
        Ok(self.read_u8()? != 0)
    }

    pub fn read_i32(&mut self) -> Result<i32> {
        let bytes = self.take(4)?;
        Ok(i32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
    }

    pub fn read_u32(&mut self) -> Result<u32> {
        let bytes = self.take(4)?;
        Ok(u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
    }

    pub fn read_i64(&mut self) -> Result<i64> {
        let bytes = self.take(8)?;
        Ok(i64::from_le_bytes([
            bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
        ]))
    }

    /// A single-precision value as its stored bit pattern, so it survives exactly rather
    /// than through a decimal rendering.
    pub fn read_f32(&mut self) -> Result<f32> {
        Ok(f32::from_bits(self.read_u32()?))
    }

    pub fn read_f64(&mut self) -> Result<f64> {
        let bytes = self.take(8)?;
        Ok(f64::from_bits(u64::from_le_bytes([
            bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
        ])))
    }

    /// A length-prefixed UTF-8 string.
    pub fn read_string(&mut self) -> Result<String> {
        let length = self.read_counter32()?;

        if length < 0 {
            return Err(Error::NegativeLength);
        }

        if length == 0 {
            return Ok(String::new());
        }

        let bytes = self.take(length as usize)?;

        std::str::from_utf8(bytes)
            .map(|text| text.to_owned())
            .map_err(|_| Error::InvalidUtf8)
    }

    /// A timestamp as .NET ticks: 100 ns units since 0001-01-01.
    ///
    /// Ticks rather than a date type, because std has none and the values a sheet can
    /// hold reach both 0001-01-01 and 9999-12-31, which most of them cannot express.
    pub fn read_datetime_ticks(&mut self) -> Result<i64> {
        self.read_i64()
    }

    /// A duration as .NET ticks.
    pub fn read_duration_ticks(&mut self) -> Result<i64> {
        self.read_i64()
    }

    /// The sixteen bytes of a uuid's .NET layout.
    pub fn read_uuid(&mut self) -> Result<Uuid> {
        let bytes = self.take(16)?;

        let mut value = [0u8; 16];
        value.copy_from_slice(bytes);

        Ok(Uuid(value))
    }

    /// An i32 written in as few bytes as its magnitude needed, either sign.
    pub fn read_optimal_i32(&mut self) -> Result<i32> {
        let encoded = self.read_varint32()?;

        // Undoes the zig-zag fold: the low bit carried the sign. The shift is on the
        // unsigned value, so the sign has to come back from that bit rather than from
        // the shift.
        Ok(((encoded >> 1) as i32) ^ -((encoded & 1) as i32))
    }

    /// A count, in the same encoding as `read_optimal_i32`.
    /// An int64 written in as few bytes as its magnitude needed, either sign.
    ///
    /// The base of a bit-packed block, which is a value of the column's own element type -
    /// an i64 column's base does not fit in thirty-two bits. One byte when it is zero.
    pub fn read_counter64(&mut self) -> Result<i64> {
        let mut encoded: u64 = 0;
        let mut shift = 0;

        loop {
            let piece = self.read_u8()?;
            encoded |= ((piece & 0x7F) as u64) << shift;

            if piece & 0x80 == 0 {
                break;
            }

            shift += 7;

            if shift > 63 {
                return Err(Error::VarintTooLong);
            }
        }

        Ok(((encoded >> 1) as i64) ^ -((encoded & 1) as i64))
    }

    /// A stream of bytes under one of the integer encodings, which is what a packed block
    /// and a presence bitmap both end in.
    ///
    /// One reader for both, so a bitmap and a packed value block cannot disagree about the
    /// same bits. The count is known before the call in both cases, so nothing here reads a
    /// length.
    pub fn read_byte_stream(
        &mut self,
        encoding: u8,
        count: usize,
        field: &'static str,
    ) -> Result<Vec<u8>> {
        if encoding == ENCODING_RAW {
            let mut out = Vec::with_capacity(count);

            for _ in 0..count {
                out.push(self.read_u8()?);
            }

            return Ok(out);
        }

        if encoding > ENCODING_DELTA_RLE {
            return Err(Error::ColumnMismatch {
                field,
                detail: "the block names an encoding that cannot carry a packed byte stream",
            });
        }

        let walking = encoding == ENCODING_DELTA || encoding == ENCODING_DELTA_RLE;
        let mut out = vec![0u8; count];

        let mut filled = 0usize;
        let mut previous = 0i32;

        // The first value of a delta stream is written outright; the rest are steps from
        // it. A run in a delta stream repeats the step, not the value, so it walks.
        if count > 0 && walking {
            previous = as_byte(self.read_optimal_i32()?, field)?;
            out[filled] = previous as u8;
            filled += 1;
        }

        while filled < count {
            let mut run = 1i32;
            let mut step = 0i32;
            let mut value = 0i32;

            match encoding {
                ENCODING_VARINT => value = as_byte(self.read_optimal_i32()?, field)?,
                ENCODING_DELTA => step = self.read_optimal_i32()?,
                ENCODING_RLE => {
                    run = self.read_counter32()?;
                    value = as_byte(self.read_optimal_i32()?, field)?;
                }
                _ => {
                    run = self.read_counter32()?;
                    step = self.read_optimal_i32()?;
                }
            }

            if run < 1 || run as usize > count - filled {
                return Err(Error::RunLengthImplausible {
                    field,
                    length: run,
                    rows_left: (count - filled) as i32,
                });
            }

            for _ in 0..run {
                if walking {
                    previous = as_byte(previous.wrapping_add(step), field)?;
                    out[filled] = previous as u8;
                } else {
                    out[filled] = value as u8;
                }

                filled += 1;
            }
        }

        Ok(out)
    }

    pub fn read_counter32(&mut self) -> Result<i32> {
        self.read_optimal_i32()
    }

    /// An enum value, which travels zig-zag encoded rather than fixed width.
    pub fn read_enum(&mut self) -> Result<i32> {
        self.read_optimal_i32()
    }

    fn read_varint32(&mut self) -> Result<u32> {
        let mut value: u32 = 0;

        let mut shift = 0;
        while shift < 35 {
            let byte = self.read_u8()?;
            value |= ((byte & 0x7F) as u32) << shift;

            if byte & 0x80 == 0 {
                return Ok(value);
            }

            shift += 7;
        }

        Err(Error::VarintTooLong)
    }
}

/// A 128 bit identifier, stored in .NET Guid byte order.
///
/// That order is not plain big-endian: the first three components are little endian and
/// the trailing eight bytes are not, which is what Display has to account for.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Uuid(pub [u8; 16]);

impl fmt::Display for Uuid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // Component order matching .NET's Guid.ToString("D").
        const ORDER: [usize; 16] = [3, 2, 1, 0, 5, 4, 7, 6, 8, 9, 10, 11, 12, 13, 14, 15];

        for (position, index) in ORDER.iter().enumerate() {
            if position == 4 || position == 6 || position == 8 || position == 10 {
                write!(f, "-")?;
            }

            write!(f, "{:02x}", self.0[*index])?;
        }

        Ok(())
    }
}

/// Reads one scalar column's values in row order, whatever the block's encoding.
///
/// The generated row loop stays a row loop; this is the one place that knows how a
/// delta accumulates, how long a run has left, or that a dictionary index is a
/// reference into strings decoded once. That last one matters beyond file size: a
/// hundred-thousand-row column with three distinct strings decodes three, and each row
/// clones from those rather than from the file.
///
/// check_column has already refused any (element, encoding) pair the spec does not
/// define, so the matches here do not re-litigate that.
///
/// Holds the reader mutably for the length of one column's row loop, which is exactly
/// how the generated code uses it: nothing else touches the reader until the cursor
/// goes out of scope at the end of the match arm.
pub struct TcbColumnCursor<'r, 'a> {
    reader: &'r mut Reader<'a>,
    field: &'static str,
    element: u8,
    encoding: u8,

    /// The block's string dictionary, decoded once and handed out per row.
    ///
    /// Whole strings whichever way they arrived: a front-coded block states only the
    /// bytes an entry does not share with the one before it, and that folding was only
    /// ever about the bytes on disk - a row wants a string.
    dictionary: Vec<String>,

    /// The block's dictionary for a fixed-width element, kept as the entries' own raw
    /// bytes so a value is reconstructed exactly as the raw layout would have read it.
    ///
    /// `value_width` is zero when the block has no such dictionary, which is what tells
    /// the value reads apart from the raw ones - an empty dictionary is not the same
    /// thing as no dictionary.
    value_dictionary: Vec<u8>,
    value_width: usize,

    // A run-length family's current run: what remains of it, and its value - which is
    // a plain value for RLE, a delta for DELTA_RLE, an index for DICT_RLE.
    run_remaining: i32,
    run_value: i32,

    // The delta family's accumulator, once started.
    previous: i32,
    started: bool,

    // Rows not yet handed out. A run that claims more than this is corrupt, and
    // catching it here names the field instead of leaving it to the block-end check.
    // For an array column this counts elements, not rows.
    rows_remaining: i32,

    /// How many elements each row holds, decoded up front for an encoded array column.
    ///
    /// Up front because the element stream follows the length stream in the block, so every
    /// length has been read by the time the first element is. `lengths_decoded` is what
    /// tells this apart from a raw array, whose lengths are interleaved with its elements
    /// and read as they are reached - an empty stream is not the same thing as no stream.
    lengths: Vec<i32>,
    lengths_decoded: bool,
    length_at: usize,

    /// Whether a float column's values are travelling as integers.
    whole_numbers: bool,

    /// A bit-packed column's bytes, decoded up front, and where in them the next value is.
    ///
    /// Up front because the bytes are themselves under an encoding and a value can cross a
    /// byte boundary, so handing values out one at a time would mean carrying a decoder and
    /// a bit offset that disagree about where they are.
    packed: Vec<u8>,
    packed_width: u32,
    packed_base: i64,
    packed_bit: u64,
}

/// A sorted dictionary whose entries state only what they do not share with the entry
/// before them.
///
/// Decoded into whole strings here rather than kept folded, because a row wants a string.
/// The scratch buffer is the previous entry: truncating it to `shared` and appending the
/// rest is the whole of the decode, and it grows to the longest entry and no further, so
/// the allocations are the strings themselves - one per distinct value, which is the point.
fn read_front_coded_dictionary(
    reader: &mut Reader<'_>, count: i32, field: &'static str,
) -> Result<Vec<String>> {
    let mut entries = Vec::new();
    entries.reserve_exact(count as usize);

    let mut scratch: Vec<u8> = Vec::new();

    for at in 0..count {
        let shared = reader.read_counter32()?;
        let rest = reader.read_counter32()?;

        // scratch still holds the previous entry, so its length is what `shared` may
        // reach - naming the entry rather than leaving a short read to the block end.
        if shared < 0 || rest < 0 || shared as usize > scratch.len() {
            return Err(Error::DictionaryPrefixImplausible {
                field,
                index: at,
                shared,
                previous: scratch.len(),
            });
        }

        scratch.truncate(shared as usize);

        if rest > 0 {
            let bytes = reader.take(rest as usize)?;
            scratch.extend_from_slice(bytes);
        }

        let text = std::str::from_utf8(&scratch).map_err(|_| Error::InvalidUtf8)?;
        entries.push(text.to_owned());
    }

    Ok(entries)
}

/// The lengths of an array column's rows, as their own encoded stream.
///
/// A varint stream, so what may be chosen for it is what may be chosen for any varint
/// column - each length as a counter32, or runs of them. Most columns have rows that are
/// all the same length, which is one run.
fn read_lengths(
    reader: &mut Reader<'_>, encoding: u8, row_count: i32, field: &'static str,
) -> Result<Vec<i32>> {
    let rows = row_count.max(0) as usize;
    let mut lengths = Vec::with_capacity(rows);

    if encoding == ENCODING_RAW {
        for _ in 0..rows {
            let length = reader.read_counter32()?;

            if length < 0 {
                return Err(Error::NegativeLength);
            }

            lengths.push(length);
        }

        return Ok(lengths);
    }

    if encoding != ENCODING_RLE {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the block names an encoding that cannot carry an array column's row \
                     lengths",
        });
    }

    while lengths.len() < rows {
        let run = reader.read_counter32()?;
        let value = reader.read_optimal_i32()?;

        let left = (rows - lengths.len()) as i32;

        if run < 1 || run > left {
            return Err(Error::RunLengthImplausible { field, length: run, rows_left: left });
        }

        if value < 0 {
            return Err(Error::NegativeLength);
        }

        for _ in 0..run {
            lengths.push(value);
        }
    }

    Ok(lengths)
}

/// A dictionary whose entries are lists of references into a table of the pieces they are
/// built from.
///
/// Two reads and a concatenation: the table, which is front coded because its own entries
/// share their fronts, and then each value as the pieces it is made of. The result is the
/// same list of whole strings every other dictionary produces, so nothing downstream of
/// here knows which kind it came from.
fn read_segment_dictionary(reader: &mut Reader<'_>, field: &'static str) -> Result<Vec<String>> {
    let segment_count = reader.read_counter32()?;

    if segment_count < 0 {
        return Err(Error::NegativeLength);
    }

    // One segment costs at least the two counters that introduce it, so a table larger
    // than the bytes left is one the exporter could not have written - checked before
    // anything is allocated for it.
    if segment_count as usize > reader.remaining() {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the segment table is larger than the file can hold",
        });
    }

    let mut segments: Vec<Vec<u8>> = Vec::with_capacity(segment_count as usize);

    for at in 0..segment_count {
        let shared = reader.read_counter32()?;
        let rest = reader.read_counter32()?;

        let previous = segments.last().map_or(0, |entry: &Vec<u8>| entry.len());

        if shared < 0 || rest < 0 || shared as usize > previous {
            return Err(Error::DictionaryPrefixImplausible {
                field,
                index: at,
                shared,
                previous,
            });
        }

        let mut segment = Vec::with_capacity(shared as usize + rest as usize);

        if shared > 0 {
            let head = &segments[segments.len() - 1][..shared as usize];
            segment.extend_from_slice(head);
        }

        if rest > 0 {
            let bytes = reader.take(rest as usize)?;
            segment.extend_from_slice(bytes);
        }

        segments.push(segment);
    }

    let count = reader.read_counter32()?;

    if count < 0 {
        return Err(Error::NegativeLength);
    }

    if count as usize > reader.remaining() {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the dictionary is larger than the file can hold",
        });
    }

    let mut entries = Vec::with_capacity(count as usize);
    let mut scratch: Vec<u8> = Vec::new();

    for _ in 0..count {
        let pieces = reader.read_counter32()?;

        if pieces < 0 {
            return Err(Error::NegativeLength);
        }

        scratch.clear();

        for _ in 0..pieces {
            let index = reader.read_counter32()?;

            if index < 0 || index as usize >= segments.len() {
                return Err(Error::DictionaryIndexOutOfRange {
                    field,
                    index,
                    entries: segments.len(),
                });
            }

            let piece = &segments[index as usize];
            scratch.extend_from_slice(piece);
        }

        let text = std::str::from_utf8(&scratch).map_err(|_| Error::InvalidUtf8)?;
        entries.push(text.to_owned());
    }

    Ok(entries)
}

impl<'r, 'a> TcbColumnCursor<'r, 'a> {
    pub fn new(
        reader: &'r mut Reader<'a>, column: &Column, row_count: i32, field: &'static str,
    ) -> Result<Self> {
        let mut dictionary = Vec::new();
        let mut value_dictionary = Vec::new();
        let mut value_width = 0;
        let mut lengths = Vec::new();
        let mut lengths_decoded = false;
        let mut whole_numbers = false;
        let mut rows_remaining = row_count;
        let mut packed = Vec::new();
        let mut packed_width = 0u32;
        let mut packed_base = 0i64;

        // An array column's block names an encoding for its elements and, where its rows
        // differ in length, one for the lengths. Both are encodings that already exist, so
        // all this does is read them and then go on being the element stream's cursor.
        let mut encoding = column.encoding;

        if encoding == ENCODING_ARRAY {
            encoding = reader.read_u8()?;

            if column.kind == KIND_ARRAY {
                let length_encoding = reader.read_u8()?;
                lengths = read_lengths(reader, length_encoding, row_count, field)?;
                lengths_decoded = true;

                let elements: i64 = lengths.iter().map(|length| *length as i64).sum();

                if elements > i32::MAX as i64 {
                    return Err(Error::ColumnMismatch {
                        field,
                        detail: "the column declares more elements than can be held",
                    });
                }

                rows_remaining = elements as i32;
            }
        }

        // A float column whose values are all whole numbers carries them as integers and
        // says which integer encoding they travel under. From here down it is that
        // encoding's cursor, and only the handing out converts back.
        if encoding == ENCODING_WHOLE {
            let inner = reader.read_u8()?;

            if inner < ENCODING_VARINT || inner > ENCODING_DELTA_RLE {
                return Err(Error::ColumnMismatch {
                    field,
                    detail: "the block names an encoding that cannot carry a whole-number \
                             column's values",
                });
            }

            encoding = inner;
            whole_numbers = true;
        }

        // A bit-packed column states the width its range needs, the base subtracted from
        // every value, and which encoding carries the packed bytes. Decoded here so that
        // handing values out is a shift and an add.
        if encoding == ENCODING_BITPACK {
            let width = reader.read_u8()?;
            let base = reader.read_counter64()?;
            let inner = reader.read_u8()?;

            if width < 1 || width > 64 {
                return Err(Error::ColumnMismatch {
                    field,
                    detail: "the block names a bit width that is not between 1 and 64",
                });
            }

            packed_width = width as u32;
            packed_base = base;

            let bits = rows_remaining.max(0) as u64 * width as u64;
            packed = reader.read_byte_stream(inner, ((bits + 7) / 8) as usize, field)?;
        }

        // A segment dictionary is built once, here, and from then on the block is a
        // dictionary with an index stream like any other - so the row-by-row paths below
        // need to know nothing about it.
        if encoding == ENCODING_DICT_SEGMENT || encoding == ENCODING_DICT_SEGMENT_RLE {
            dictionary = read_segment_dictionary(reader, field)?;

            encoding = if encoding == ENCODING_DICT_SEGMENT {
                ENCODING_DICT
            } else {
                ENCODING_DICT_RLE
            };
        } else {
            let plain_dictionary = encoding == ENCODING_DICT || encoding == ENCODING_DICT_RLE;

            let front_dictionary =
                encoding == ENCODING_DICT_FRONT || encoding == ENCODING_DICT_FRONT_RLE;

            if plain_dictionary || front_dictionary {
                let count = reader.read_counter32()?;
                if count < 0 {
                    return Err(Error::NegativeLength);
                }

                if front_dictionary {
                    dictionary = read_front_coded_dictionary(reader, count, field)?;
                } else if column.element == ELEMENT_STRING {
                    dictionary.reserve_exact(count as usize);
                    for _ in 0..count {
                        dictionary.push(reader.read_string()?);
                    }
                } else {
                    // A fixed-width element: the entries are the value's own bytes, so they
                    // are taken as bytes and turned into values only when a row asks.
                    value_width = if column.element == ELEMENT_F32 { 4 } else { 8 };
                    value_dictionary.reserve_exact(count as usize * value_width);

                    for _ in 0..count {
                        let bytes = reader.take(value_width)?;
                        value_dictionary.extend_from_slice(bytes);
                    }
                }
            }
        }

        Ok(TcbColumnCursor {
            reader,
            field,
            element: column.element,
            encoding,
            dictionary,
            value_dictionary,
            value_width,
            run_remaining: 0,
            run_value: 0,
            previous: 0,
            started: false,
            rows_remaining,
            lengths,
            lengths_decoded,
            length_at: 0,
            whole_numbers,
            packed,
            packed_width,
            packed_base,
            packed_bit: 0,
        })
    }

    /// How many elements the next row of an array column holds.
    ///
    /// One call whichever way the block is laid out. An encoded array decoded every length
    /// before the first element was read, so this hands out what it already has; a raw one
    /// states each row's length in front of that row's elements, so this reads it where it
    /// stands.
    pub fn next_length(&mut self) -> Result<i32> {
        if self.lengths_decoded {
            let at = self.length_at;

            if at >= self.lengths.len() {
                return Err(Error::ColumnMismatch {
                    field: self.field,
                    detail: "the column has no more rows to read",
                });
            }

            self.length_at = at + 1;

            return Ok(self.lengths[at]);
        }

        let length = self.reader.read_counter32()?;

        if length < 0 {
            return Err(Error::NegativeLength);
        }

        Ok(length)
    }

    /// The next i32 - which also serves enums, and reference indexes.
    /// The next value of a bit-packed stream: the packed bits, over the block's base.
    ///
    /// A value may cross a byte boundary, so this walks bits rather than bytes. The
    /// addition wraps, mirroring the writer's wrapping subtraction.
    fn next_packed(&mut self) -> i64 {
        let mut slot: u64 = 0;

        for at in 0..self.packed_width {
            let bit = self.packed_bit;

            if self.packed[(bit >> 3) as usize] >> (bit & 7) & 1 != 0 {
                slot |= 1u64 << at;
            }

            self.packed_bit += 1;
        }

        self.packed_base.wrapping_add(slot as i64)
    }

    pub fn next_i32(&mut self) -> Result<i32> {
        self.rows_remaining -= 1;

        if self.encoding == ENCODING_BITPACK {
            return Ok(self.next_packed() as i32);
        }

        match self.encoding {
            ENCODING_RAW => {
                if self.element == ELEMENT_I32 {
                    self.reader.read_i32()
                } else {
                    self.reader.read_optimal_i32()
                }
            }

            ENCODING_VARINT => self.reader.read_optimal_i32(),

            ENCODING_DELTA => {
                // The addition wraps on purpose, mirroring the writer's wrapping
                // subtraction; together they are exact for every i32 pair.
                if self.started {
                    self.previous = self.previous.wrapping_add(self.reader.read_optimal_i32()?);
                } else {
                    self.previous = self.reader.read_optimal_i32()?;
                    self.started = true;
                }

                Ok(self.previous)
            }

            ENCODING_RLE => {
                if self.run_remaining == 0 {
                    self.read_run()?;
                }

                self.run_remaining -= 1;
                Ok(self.run_value)
            }

            // ENCODING_DELTA_RLE; check_column refused everything else.
            _ => {
                if !self.started {
                    self.previous = self.reader.read_optimal_i32()?;
                    self.started = true;
                    return Ok(self.previous);
                }

                if self.run_remaining == 0 {
                    self.read_run()?;
                }

                self.run_remaining -= 1;
                self.previous = self.previous.wrapping_add(self.run_value);
                Ok(self.previous)
            }
        }
    }

    /// An i64 member: from an i64 column raw or through its dictionary, and from anything
    /// narrower by decoding an i32 and widening it.
    pub fn next_i64(&mut self) -> Result<i64> {
        if self.element != ELEMENT_I64 {
            return Ok(self.next_i32()? as i64);
        }

        if self.encoding == ENCODING_BITPACK {
            self.rows_remaining -= 1;

            return Ok(self.next_packed());
        }

        if self.value_width != 0 {
            let bytes = self.next_value_entry()?;

            return Ok(i64::from_le_bytes([
                bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
            ]));
        }

        self.rows_remaining -= 1;
        self.reader.read_i64()
    }

    /// An f32 member: raw, the dictionary entry's exact bit pattern, or a whole number.
    pub fn next_f32(&mut self) -> Result<f32> {
        if self.whole_numbers {
            return Ok(self.next_i32()? as f32);
        }

        if self.value_width != 0 {
            let bytes = self.next_value_entry()?;

            return Ok(f32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]));
        }

        self.rows_remaining -= 1;
        self.reader.read_f32()
    }

    /// An f64 member: from f64 or f32 - either of them raw or dictionary-encoded - and
    /// from an i32 column by decoding and widening.
    pub fn next_f64(&mut self) -> Result<f64> {
        if self.whole_numbers {
            return Ok(self.next_i32()? as f64);
        }

        match self.element {
            ELEMENT_F64 => {
                if self.value_width != 0 {
                    let bytes = self.next_value_entry()?;

                    return Ok(f64::from_le_bytes([
                        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6],
                        bytes[7],
                    ]));
                }

                self.rows_remaining -= 1;
                self.reader.read_f64()
            }

            ELEMENT_F32 => Ok(self.next_f32()? as f64),
            _ => Ok(self.next_i32()? as f64),
        }
    }

    /// A bool member: one byte raw, or a run of them.
    pub fn next_bool(&mut self) -> Result<bool> {
        if self.encoding == ENCODING_RLE || self.encoding == ENCODING_BITPACK {
            return Ok(self.next_i32()? != 0);
        }

        self.rows_remaining -= 1;
        self.reader.read_bool()
    }

    /// The bytes of the next row's dictionary entry, for a fixed-width element.
    ///
    /// Borrowed from the cursor rather than copied out, which the caller can hold only
    /// until it has built its value - which is all it wants them for.
    fn next_value_entry(&mut self) -> Result<&[u8]> {
        self.rows_remaining -= 1;

        let index = if self.encoding == ENCODING_DICT {
            self.reader.read_counter32()?
        } else {
            if self.run_remaining == 0 {
                self.read_run()?;
            }

            self.run_remaining -= 1;
            self.run_value
        };

        let entries = self.value_dictionary.len() / self.value_width;

        if index < 0 || index as usize >= entries {
            return Err(Error::DictionaryIndexOutOfRange { field: self.field, index, entries });
        }

        let at = index as usize * self.value_width;

        Ok(&self.value_dictionary[at..at + self.value_width])
    }

    /// The next string - a clone of the dictionary's entry where the block has one.
    pub fn next_string(&mut self) -> Result<String> {
        self.rows_remaining -= 1;

        match self.encoding {
            ENCODING_RAW => self.reader.read_string(),

            ENCODING_DICT | ENCODING_DICT_FRONT => {
                let index = self.reader.read_counter32()?;
                self.dictionary_entry(index)
            }

            // ENCODING_DICT_RLE and ENCODING_DICT_FRONT_RLE; check_column refused
            // everything else. A front-coded dictionary is whole strings by now, so the
            // index stream is the only thing left to tell them apart - and it does not.
            _ => {
                if self.run_remaining == 0 {
                    self.read_run()?;
                }

                self.run_remaining -= 1;
                self.dictionary_entry(self.run_value)
            }
        }
    }

    /// Up to `limit` rows that all hold the next value, as `(count, value)`. The count
    /// is always at least 1.
    ///
    /// This is what makes a run cost one call instead of one per row: the generated loop
    /// asks once, then assigns the value that many times. An encoding that cannot promise
    /// sameness cheaply answers 1, so the caller's loop is correct over every encoding
    /// and only faster over runs.
    pub fn next_same_i32(&mut self, limit: i32) -> Result<(i32, i32)> {
        if self.encoding == ENCODING_RLE {
            self.rows_remaining -= 1;
            if self.run_remaining == 0 {
                self.read_run()?;
            }

            let n = self.run_remaining.min(limit);
            self.run_remaining -= n;
            self.rows_remaining -= n - 1;

            return Ok((n, self.run_value));
        }

        if self.encoding == ENCODING_DELTA_RLE && self.started {
            self.rows_remaining -= 1;
            if self.run_remaining == 0 {
                self.read_run()?;
            }

            if self.run_value == 0 {
                // A zero-delta run is a run of one value.
                let n = self.run_remaining.min(limit);
                self.run_remaining -= n;
                self.rows_remaining -= n - 1;

                return Ok((n, self.previous));
            }

            self.run_remaining -= 1;
            self.previous = self.previous.wrapping_add(self.run_value);

            return Ok((1, self.previous));
        }

        Ok((1, self.next_i32()?))
    }

    /// The string counterpart of [`Self::next_same_i32`].
    pub fn next_same_string(&mut self, limit: i32) -> Result<(i32, String)> {
        if self.encoding == ENCODING_DICT_RLE || self.encoding == ENCODING_DICT_FRONT_RLE {
            self.rows_remaining -= 1;
            if self.run_remaining == 0 {
                self.read_run()?;
            }

            let n = self.run_remaining.min(limit);
            self.run_remaining -= n;
            self.rows_remaining -= n - 1;
            let value = self.dictionary_entry(self.run_value)?;

            return Ok((n, value));
        }

        Ok((1, self.next_string()?))
    }

    fn read_run(&mut self) -> Result<()> {
        let length = self.reader.read_counter32()?;

        // + 1 because the row this run was read for is already counted out of
        // rows_remaining by its next_* call.
        if length < 1 || length > self.rows_remaining + 1 {
            return Err(Error::RunLengthImplausible {
                field: self.field,
                length,
                rows_left: self.rows_remaining + 1,
            });
        }

        self.run_remaining = length;
        self.run_value = self.reader.read_optimal_i32()?;

        Ok(())
    }

    fn dictionary_entry(&self, index: i32) -> Result<String> {
        if index < 0 || index as usize >= self.dictionary.len() {
            return Err(Error::DictionaryIndexOutOfRange {
                field: self.field,
                index,
                entries: self.dictionary.len(),
            });
        }

        Ok(self.dictionary[index as usize].clone())
    }
}

/// Reads and checks a table file's header, returning the row count that follows it.
///
/// The flags byte says what was done to the body, and no bit of it is accepted. [`open`]
/// clears the encryption bit on the plaintext it returns, so a reader that still meets it
/// was handed the ciphertext without the key - and naming that beats letting the block
/// lengths make what they can of it. Any other bit names handling this build does not have.
pub fn read_table_header(reader: &mut Reader<'_>) -> Result<Header> {
    // Checked again here rather than only in open, because a reader can be handed bytes that
    // never went through it.
    if reader.read_u32()? != u32::from_le_bytes(*MAGIC) {
        return Err(Error::NotATableFile);
    }

    let version = reader.read_u32()?;

    if version != FORMAT_VERSION {
        return Err(Error::UnsupportedVersion { found: version, expected: FORMAT_VERSION });
    }

    let flags = reader.read_u8()?;

    if flags & FLAG_ENCRYPTED != 0 {
        return Err(Error::NotDecrypted);
    }

    if flags != 0 {
        return Err(Error::UnsupportedFeatures);
    }

    // The cipher byte, the nonce, the MAC and the key check. open has dealt with all four by
    // now; what is left is to be standing at the body.
    reader.skip((HEADER_SIZE - CIPHER_OFFSET) as i32)?;

    let count = reader.read_counter32()?;
    if count < 0 {
        return Err(Error::NegativeLength);
    }

    let column_count = reader.read_counter32()?;
    if column_count < 0 {
        return Err(Error::NegativeLength);
    }

    let mut columns = Vec::with_capacity(column_count as usize);

    for _ in 0..column_count {
        let tag = reader.read_counter32()?;
        let wire = reader.read_u8()?;
        let encoding = reader.read_u8()?;
        let byte_length = reader.read_u32()? as i32;

        columns.push(Column {
            tag,
            element: wire & 0x0f,
            kind: (wire >> 4) & 0x03,
            nullable: wire & 0x40 != 0,
            element_nullable: wire & 0x80 != 0,
            encoding,
            byte_length,
        });
    }

    // What the descriptors say about the file, checked before anybody allocates for the
    // row count. The blocks are all that follows the header, so their declared lengths have
    // to add up to the bytes left. A raw block also costs at least one byte per row - a
    // varint's shortest form, an empty string's length prefix, a variable array's counter -
    // so a larger row count is one the exporter could not have written. An encoded block
    // has no such floor; its decode checks run sums and dictionary bounds instead.

    let available = reader.remaining() as i32;
    let mut declared: i32 = 0;

    for column in &columns {
        if column.byte_length < 0 || column.byte_length > available - declared {
            return Err(Error::ColumnLengthImplausible {
                tag: column.tag,
                byte_length: column.byte_length,
            });
        }

        declared += column.byte_length;

        if column.encoding == ENCODING_RAW && count > column.byte_length {
            return Err(Error::RowCountImplausible {
                rows: count,
                tag: column.tag,
                byte_length: column.byte_length,
            });
        }

    }

    if declared != available {
        return Err(Error::HeaderLengthMismatch { declared, available });
    }

    Ok(Header { row_count: count, columns })
}

/// A nullable column's presence bitmap, which sits at the front of its block.
///
/// Empty for a column that is not optional, which is what lets the generated code call
/// [`is_present`] without testing first.
pub fn read_presence(reader: &mut Reader<'_>, column: &Column, row_count: i32) -> Result<Vec<u8>> {
    if !column.nullable {
        return Ok(Vec::new());
    }

    // The bitmap is a bit-packed boolean column of width one, so it carries an encoding
    // byte and is laid out by the same choice a packed value block uses. Its width and base
    // are known in advance, which is why it does not carry them.
    let encoding = reader.read_u8()?;

    reader.read_byte_stream(encoding, (row_count.max(0) as usize + 7) / 8, "a presence bitmap")
}

/// A column's element bitmap, which sits behind the row bitmap and in front of the values.
///
/// Empty for a column that does not carry one. Its length is written ahead of it as a
/// counter32, because a variable-length column's total is the sum of its row lengths and
/// those live inside the value block - a reader meeting the bitmap first would have nothing
/// to size it by. spec/types/nullable-array-elements.md.
pub fn read_element_presence(reader: &mut Reader<'_>, column: &Column) -> Result<Vec<u8>> {
    if !column.element_nullable {
        return Ok(Vec::new());
    }

    let elements = reader.read_counter32()?;
    let encoding = reader.read_u8()?;

    reader.read_byte_stream(
        encoding,
        (elements.max(0) as usize + 7) / 8,
        "an element presence bitmap",
    )
}

/// Whether a row has a value, for a column that says which do.
///
/// An empty bitmap means the column is not optional, and then every row has one.
pub fn is_present(presence: &[u8], row: usize) -> bool {
    presence.is_empty() || presence[row >> 3] & (1 << (row & 7)) != 0
}

/// That a column is what the generated member expects, or a lossless promotion of it.
/// The same, for a member whose array elements may be absent.
pub fn check_column_with_elements(
    column: &Column, field: &'static str, kind: u8,  nullable: bool,
    accepted: &[u8],
) -> Result<()> {
    check_element_nullable(column, field, true)?;
    check_column_shape(column, field, kind, nullable, accepted)
}

/// That the file and the generated member agree about the element bitmap.
///
/// The same statement `check_column` makes about the row one: code not expecting a bitmap
/// would read it as values. spec/types/nullable-array-elements.md.
fn check_element_nullable(column: &Column, field: &'static str, expected: bool) -> Result<()> {
    if column.element_nullable != expected {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the file and the generated member disagree about whether this column's                      elements are optional; the schema changed, regenerate the code or                      rebuild the data",
        });
    }

    Ok(())
}

pub fn check_column(
    column: &Column, field: &'static str, kind: u8,  nullable: bool,
    accepted: &[u8],
) -> Result<()> {
    check_element_nullable(column, field, false)?;
    check_column_shape(column, field, kind, nullable, accepted)
}

fn check_column_shape(
    column: &Column, field: &'static str, kind: u8,  nullable: bool,
    accepted: &[u8],
) -> Result<()> {
    // Nullability is part of the shape: a file that says optional puts a presence bitmap in
    // front of the block, and code not expecting one reads the bitmap as values. So adding
    // or removing a `?` is a schema change like any other, caught here rather than in
    // whatever the misread bytes happened to mean.
    if column.nullable != nullable {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the file and the generated member disagree about whether this column                      is optional; the schema changed, regenerate the code or rebuild the data",
        });
    }

    // A negative count says the member claims no length: how many elements a row holds is
    // what the file states. The kind is still the member's claim.
    // spec/types/nullable-array-elements.md.
    if column.kind != kind {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the column's shape does not match the generated member; the schema \
                     changed shape, regenerate the code or rebuild the data",
        });
    }

    // An encoding this build cannot decode - or one the spec does not define for this
    // element - is refused by name, exactly like an element it cannot read. An unknown
    // column's encoding never gets here - a skip is a skip whatever the block's layout.
    if !encoding_supported(column) {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the column uses an encoding this reader cannot decode for its \
                     element type; regenerate the code or rebuild the data",
        });
    }

    if !accepted.contains(&column.element) {
        return Err(Error::ColumnMismatch {
            field,
            detail: "the column's element type is one this member cannot read; the column \
                     changed type incompatibly, regenerate the code or rebuild the data",
        });
    }

    Ok(())
}

/// The (element, encoding) pairs the spec defines. Integers take the integer encodings,
/// strings the dictionary ones, and an array takes the composition that applies all of
/// those to its elements.
/// A decoded value that has to be a byte, or the block is corrupt.
fn as_byte(value: i32, field: &'static str) -> Result<i32> {
    if !(0..=255).contains(&value) {
        return Err(Error::ColumnMismatch {
            field,
            detail: "a packed byte stream decoded a value that is not a byte",
        });
    }

    Ok(value)
}

fn encoding_supported(column: &Column) -> bool {
    if column.encoding == ENCODING_RAW {
        return true;
    }

    // An array's block says what its elements use, and the element encoding is checked as
    // it is read rather than here - the descriptor carries only the outer one, so this is
    // as far as the descriptor can be checked.
    if column.kind != KIND_SCALAR {
        return column.encoding == ENCODING_ARRAY;
    }

    match column.element {
        ELEMENT_BOOL | ELEMENT_VARINT => {
            column.encoding == ENCODING_RLE || column.encoding == ENCODING_BITPACK
        }

        ELEMENT_I32 => {
            (column.encoding >= ENCODING_VARINT && column.encoding <= ENCODING_DELTA_RLE)
                || column.encoding == ENCODING_BITPACK
        }

        // The dictionary is parameterized by element, so these three reach it with
        // entries that are simply their own raw bytes.
        ELEMENT_I64 => {
            column.encoding == ENCODING_DICT
                || column.encoding == ENCODING_DICT_RLE
                || column.encoding == ENCODING_BITPACK
        }

        // A float column additionally reaches the integer encodings, through the block
        // that says its values are whole numbers.
        ELEMENT_F32 | ELEMENT_F64 => {
            column.encoding == ENCODING_DICT
                || column.encoding == ENCODING_DICT_RLE
                || column.encoding == ENCODING_WHOLE
        }

        // And a string dictionary can be front coded or built from segments, both of which
        // are meaningless for a fixed-width element and refused for one.
        ELEMENT_STRING => {
            (column.encoding >= ENCODING_DICT && column.encoding <= ENCODING_DICT_FRONT_RLE)
                || column.encoding == ENCODING_DICT_SEGMENT
                || column.encoding == ENCODING_DICT_SEGMENT_RLE
        }

        _ => false,
    }
}

/// That a block was consumed exactly: a mismatch is a format disagreement, and stopping
/// here names the column instead of corrupting the next.
pub fn check_block_end(reader: &Reader<'_>, column: &Column, expected_end: usize) -> Result<()> {
    if reader.position() != expected_end {
        return Err(Error::BlockLengthMismatch { tag: column.tag });
    }

    Ok(())
}

/// Reads a whole file into memory.
pub fn read_all_bytes(filename: &Path) -> Result<Vec<u8>> {
    Ok(fs::read(filename)?)
}

/// A file's plaintext bytes, checked against its MAC on the way.
///
/// Call this on the bytes before handing them to a [`Reader`]. A file that is neither
/// encrypted nor authenticated comes back untouched, so the call belongs in the load path
/// whether or not the project uses either.
///
/// The order is verify, then decrypt. The tag covers the file as it is stored, so an altered
/// file is refused before the key is used on it, and the header - the flags, the cipher
/// byte, the nonce - is covered along with the body.
///
/// Decryption happens in place, and what comes back is a window onto the same buffer rather
/// than a copy of it - which is why this takes the bytes mutably and hands back a borrow of
/// them. The fields it consumes are returned to what a plain file has in them, so calling it
/// twice on the same buffer is the same as calling it once.
///
/// What the two layers are and are not for: both keys ship inside the client that reads the
/// file. Encryption stops a data file being read in an editor; the MAC stops an edited one
/// loading. Neither stops anyone who can take the keys out of the client, and no format
/// does.
///
/// `mac_key` is empty when the project does not sign its files. A reader that has one
/// refuses a file that carries no MAC: the field being zero is how a file says it is
/// unauthenticated, so accepting that from a project that signs its files would put the
/// check sixteen zero bytes away from being removed.
///
/// `verify_mac` false skips the check. For tools and for measuring load time - and no weaker
/// than it looks, because anyone who can flip this flag in a shipped binary can read the key
/// out of the same binary.
pub fn open<'a>(
    data: &'a mut [u8],
    key: &[u8],
    mac_key: &[u8],
    verify_mac: bool,
) -> Result<&'a [u8]> {
    if data.len() < HEADER_SIZE {
        return Err(Error::Truncated { position: 0, length: data.len(), wanted: HEADER_SIZE });
    }

    if data[MAGIC_OFFSET..MAGIC_OFFSET + 4] != *MAGIC {
        return Err(Error::NotATableFile);
    }

    if verify_mac {
        check_mac(data, mac_key)?;
    }

    if data[FLAGS_OFFSET] & FLAG_ENCRYPTED == 0 {
        return Ok(data);
    }

    if data[CIPHER_OFFSET] != CIPHER_CHACHA20 {
        return Err(Error::UnknownCipher { cipher: data[CIPHER_OFFSET] });
    }

    if key.len() != 32 {
        return Err(Error::MissingKey);
    }

    // Copied out because the keystream is applied to the same buffer it sits in.
    let mut nonce = [0u8; NONCE_SIZE];
    nonce.copy_from_slice(&data[NONCE_OFFSET..NONCE_OFFSET + NONCE_SIZE]);

    chacha20_apply(key, &nonce, &mut data[KEY_CHECK_OFFSET..]);

    if data[KEY_CHECK_OFFSET..KEY_CHECK_OFFSET + 4] != *MAGIC {
        return Err(Error::WrongKey);
    }

    // Back to what a plain file holds in these bytes, so that a second call over the same
    // buffer passes it through instead of decrypting it again.
    data[FLAGS_OFFSET] &= !FLAG_ENCRYPTED;
    data[CIPHER_OFFSET] = CIPHER_NONE;
    data[NONCE_OFFSET..NONCE_OFFSET + NONCE_SIZE].fill(0);

    Ok(data)
}

/// The MAC field against the file's own bytes, and against whether a key was given.
fn check_mac(data: &[u8], mac_key: &[u8]) -> Result<()> {
    // Nothing to check with. A file that carries a tag is read anyway rather than refused:
    // this reader has no way to tell whether the tag is good, and a client built before the
    // project turned MACs on is one this format has promised can still read what it is sent.
    if mac_key.is_empty() {
        return Ok(());
    }

    if mac_key.len() != 32 {
        return Err(Error::MissingKey);
    }

    if data[MAC_OFFSET..MAC_OFFSET + MAC_SIZE].iter().all(|byte| *byte == 0) {
        return Err(Error::MissingMac);
    }

    let expected = hmac_sha256(mac_key, data);

    // Every byte, always: a comparison that returns early tells the caller how far it got.
    let mut difference = 0u8;

    for at in 0..MAC_SIZE {
        difference |= expected[at] ^ data[MAC_OFFSET + at];
    }

    if difference != 0 {
        return Err(Error::MacMismatch);
    }

    Ok(())
}

// HMAC-SHA-256 over the file, truncated to the sixteen bytes the header keeps for it.
//
// Written out here for the same reason the cipher is: SHA-256 lives in a crate, and this
// runtime has no dependencies and is to keep none.
//
// What the tag catches is what the structural checks cannot. A block length that does not
// add up is a malformed file and the reader says so; four other bytes in an f32 column is a
// well-formed file holding a different number, and no check over a file's shape can tell
// that from data that was always there.

/// The tag for a file: HMAC-SHA-256 over every byte but the sixteen the tag lives in.
///
/// Skipping them is the same as zeroing them and cheaper by a copy of the file.
fn hmac_sha256(key: &[u8], data: &[u8]) -> [u8; 32] {
    let mut block = [0u8; 64];

    // A key longer than the block is hashed first; ours is thirty-two bytes, but the rule is
    // part of HMAC and leaving it out would make this agree with nothing.
    if key.len() > 64 {
        block[..32].copy_from_slice(&sha256(&[key]));
    } else {
        block[..key.len()].copy_from_slice(key);
    }

    let mut inner = [0u8; 64];
    let mut outer = [0u8; 64];

    for at in 0..64 {
        inner[at] = block[at] ^ 0x36;
        outer[at] = block[at] ^ 0x5c;
    }

    let inner_digest = sha256(&[&inner, &data[..MAC_OFFSET], &data[KEY_CHECK_OFFSET..]]);

    sha256(&[&outer, &inner_digest])
}

/// The round constants: the fractional parts of the cube roots of the first 64 primes.
const SHA256_K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4,
    0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe,
    0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
    0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
    0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc,
    0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
    0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116,
    0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7,
    0xc67178f2,
];

/// SHA-256 of the pieces, hashed as though they were one message.
///
/// Pieces rather than one slice because every call here has more than one and none of them
/// wants the copy that joining would cost: HMAC hashes a pad followed by the message, and
/// the message itself is the file with a hole in the middle of it.
fn sha256(pieces: &[&[u8]]) -> [u8; 32] {
    let mut state: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
        0x5be0cd19,
    ];

    let mut schedule = [0u32; 64];
    let mut block = [0u8; 64];

    let mut filled = 0usize;
    let mut length = 0u64;

    for piece in pieces {
        length += piece.len() as u64;

        let mut at = 0usize;

        // The partial block first, then whole blocks straight out of the piece: the copy
        // into `block` is only for the bytes that straddle a boundary.
        while at < piece.len() {
            if filled == 0 && piece.len() - at >= 64 {
                sha256_block(&mut state, &mut schedule, &piece[at..at + 64]);
                at += 64;
                continue;
            }

            let taking = core::cmp::min(64 - filled, piece.len() - at);
            block[filled..filled + taking].copy_from_slice(&piece[at..at + taking]);

            filled += taking;
            at += taking;

            if filled == 64 {
                let full = block;
                sha256_block(&mut state, &mut schedule, &full);
                filled = 0;
            }
        }
    }

    // The padding: a set bit, zeros, and the message length in bits as a 64-bit big-endian
    // number. Two blocks when the length does not fit in the one that is open.
    let mut tail = [0u8; 128];
    let tail_length = if filled + 9 > 64 { 128 } else { 64 };

    tail[..filled].copy_from_slice(&block[..filled]);
    tail[filled] = 0x80;
    tail[tail_length - 8..tail_length].copy_from_slice(&(length * 8).to_be_bytes());

    let mut at = 0usize;
    while at < tail_length {
        let full: [u8; 64] = tail[at..at + 64].try_into().unwrap();
        sha256_block(&mut state, &mut schedule, &full);
        at += 64;
    }

    let mut digest = [0u8; 32];

    for at in 0..8 {
        digest[at * 4..at * 4 + 4].copy_from_slice(&state[at].to_be_bytes());
    }

    digest
}

/// One 64-byte block of the compression function.
fn sha256_block(state: &mut [u32; 8], schedule: &mut [u32; 64], data: &[u8]) {
    for at in 0..16 {
        schedule[at] = u32::from_be_bytes([
            data[at * 4],
            data[at * 4 + 1],
            data[at * 4 + 2],
            data[at * 4 + 3],
        ]);
    }

    for at in 16..64 {
        let before = schedule[at - 15];
        let near = schedule[at - 2];

        let s0 = before.rotate_right(7) ^ before.rotate_right(18) ^ (before >> 3);
        let s1 = near.rotate_right(17) ^ near.rotate_right(19) ^ (near >> 10);

        schedule[at] = schedule[at - 16]
            .wrapping_add(s0)
            .wrapping_add(schedule[at - 7])
            .wrapping_add(s1);
    }

    let (mut a, mut b, mut c, mut d) = (state[0], state[1], state[2], state[3]);
    let (mut e, mut f, mut g, mut h) = (state[4], state[5], state[6], state[7]);

    for at in 0..64 {
        let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
        let choice = (e & f) ^ (!e & g);
        let one = h
            .wrapping_add(s1)
            .wrapping_add(choice)
            .wrapping_add(SHA256_K[at])
            .wrapping_add(schedule[at]);

        let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
        let majority = (a & b) ^ (a & c) ^ (b & c);
        let two = s0.wrapping_add(majority);

        h = g;
        g = f;
        f = e;
        e = d.wrapping_add(one);
        d = c;
        c = b;
        b = a;
        a = one.wrapping_add(two);
    }

    state[0] = state[0].wrapping_add(a);
    state[1] = state[1].wrapping_add(b);
    state[2] = state[2].wrapping_add(c);
    state[3] = state[3].wrapping_add(d);
    state[4] = state[4].wrapping_add(e);
    state[5] = state[5].wrapping_add(f);
    state[6] = state[6].wrapping_add(g);
    state[7] = state[7].wrapping_add(h);
}

/// Exclusive-ors the ChaCha20 keystream of RFC 8439 over `data`, in place.
///
/// Here rather than from a crate because the runtime has no dependencies and is to keep
/// none, and because the usual offering is an authenticated construction, which changes
/// the length. This format wants a plain keystream: applying it leaves every byte count as
/// it was, so the structural checks - the block lengths that must sum exactly - hold over
/// the ciphertext unchanged.
///
/// One routine for both directions, which is what a stream cipher is: the keystream
/// depends only on the key, the nonce and the position, so applying it twice returns what
/// went in. The block counter starts at zero.
fn chacha20_apply(key: &[u8], nonce: &[u8; 12], data: &mut [u8]) {
    let mut state = [0u32; 16];

    // "expand 32-byte k", as four little-endian words.
    state[0] = 0x6170_7865;
    state[1] = 0x3320_646e;
    state[2] = 0x7962_2d32;
    state[3] = 0x6b20_6574;

    for at in 0..8 {
        state[4 + at] =
            u32::from_le_bytes([key[at * 4], key[at * 4 + 1], key[at * 4 + 2], key[at * 4 + 3]]);
    }

    state[12] = 0;

    for at in 0..3 {
        state[13 + at] = u32::from_le_bytes([
            nonce[at * 4],
            nonce[at * 4 + 1],
            nonce[at * 4 + 2],
            nonce[at * 4 + 3],
        ]);
    }

    let mut keystream = [0u8; 64];

    for chunk in data.chunks_mut(64) {
        chacha20_block(&state, &mut keystream);

        for (at, byte) in chunk.iter_mut().enumerate() {
            *byte ^= keystream[at];
        }

        state[12] = state[12].wrapping_add(1);
    }
}

/// One 64-byte keystream block: twenty rounds over a copy of the state.
fn chacha20_block(state: &[u32; 16], keystream: &mut [u8; 64]) {
    let mut working = *state;

    // Ten double rounds. Each is four column quarter-rounds and four diagonal ones, which
    // between them let every word reach every other.
    for _ in 0..10 {
        chacha20_quarter_round(&mut working, 0, 4, 8, 12);
        chacha20_quarter_round(&mut working, 1, 5, 9, 13);
        chacha20_quarter_round(&mut working, 2, 6, 10, 14);
        chacha20_quarter_round(&mut working, 3, 7, 11, 15);

        chacha20_quarter_round(&mut working, 0, 5, 10, 15);
        chacha20_quarter_round(&mut working, 1, 6, 11, 12);
        chacha20_quarter_round(&mut working, 2, 7, 8, 13);
        chacha20_quarter_round(&mut working, 3, 4, 9, 14);
    }

    // Added back to the state it started from, which is what stops the rounds being
    // reversible and so the keystream being recoverable.
    for at in 0..16 {
        let word = working[at].wrapping_add(state[at]);
        keystream[at * 4..at * 4 + 4].copy_from_slice(&word.to_le_bytes());
    }
}

fn chacha20_quarter_round(block: &mut [u32; 16], a: usize, b: usize, c: usize, d: usize) {
    block[a] = block[a].wrapping_add(block[b]);
    block[d] = (block[d] ^ block[a]).rotate_left(16);

    block[c] = block[c].wrapping_add(block[d]);
    block[b] = (block[b] ^ block[c]).rotate_left(12);

    block[a] = block[a].wrapping_add(block[b]);
    block[d] = (block[d] ^ block[a]).rotate_left(8);

    block[c] = block[c].wrapping_add(block[d]);
    block[b] = (block[b] ^ block[c]).rotate_left(7);
}
